-- Every WhatsApp template on the SmartChat account, so the Templates page lists them all. Status is
-- as read off the portal on 2026-11-09; Refresh or a manual edit keeps it current. Each is sent by its
-- own flow or the catalogue, not as a stored template. A null body means the wording is only on SmartChat.
insert into message_template (channel, name, body, category, status, provider_id, rule, system_managed, created_by_name)
select 'WHATSAPP', v.name, v.body, v.category, v.status, v.provider, 'ANY', true, 'SmartChat portal'
from (values
    ('dhanbt', null, 'MARKETING', 'ACTIVE', 'dhanbt'),
    ('dhanboost', null, 'MARKETING', 'ACTIVE', 'dhanboost'),
    ('db_kyc_approved', null, 'SERVICE', 'ACTIVE', 'db_kyc_approved'),
    ('db_kyc_rejected', null, 'SERVICE', 'ACTIVE', 'db_kyc_rejected'),
    ('db_kyc_reminder', null, 'SERVICE', 'ACTIVE', 'db_kyc_reminder'),
    ('db_reborrow_preapproved', null, 'MARKETING', 'ACTIVE', 'db_reborrow_preapproved'),
    ('db_application_declined', null, 'SERVICE', 'ACTIVE', 'db_application_declined'),
    ('db_amount_revised', null, 'SERVICE', 'ACTIVE', 'db_amount_revised'),
    ('db_reborrow_approved', null, 'SERVICE', 'ACTIVE', 'db_reborrow_approved'),
    ('db_limit_increased', null, 'SERVICE', 'ACTIVE', 'db_limit_increased'),
    ('db_bureau_question', null, 'SERVICE', 'REJECTED', 'db_bureau_question'),
    ('db_loan_disbursed', null, 'SERVICE', 'ACTIVE', 'db_loan_disbursed'),
    ('db_disbursal_declined', null, 'SERVICE', 'ACTIVE', 'db_disbursal_declined'),
    ('db_loan_sanctioned', null, 'SERVICE', 'ACTIVE', 'db_loan_sanctioned'),
    ('db_back_in_review', null, 'SERVICE', 'ACTIVE', 'db_back_in_review'),
    ('db_sanction_letter_signed', null, 'SERVICE', 'ACTIVE', 'db_sanction_letter_signed'),
    ('db_payment_recorded', null, 'SERVICE', 'ACTIVE', 'db_payment_recorded'),
    ('db_repayment_rejected', null, 'SERVICE', 'ACTIVE', 'db_repayment_rejected'),
    ('db_payment_due_soon', null, 'SERVICE', 'ACTIVE', 'db_payment_due_soon'),
    ('db_payment_overdue', null, 'SERVICE', 'ACTIVE', 'db_payment_overdue'),
    ('db_settlement_approved', null, 'SERVICE', 'ACTIVE', 'db_settlement_approved'),
    ('db_referral_reward', null, 'SERVICE', 'ACTIVE', 'db_referral_reward'),
    ('db_loan_closed', null, 'SERVICE', 'ACTIVE', 'db_loan_closed'),
    ('db_repayment_verified', null, 'SERVICE', 'ACTIVE', 'db_repayment_verified'),
    ('db_application_cancelled', null, 'SERVICE', 'ACTIVE', 'db_application_cancelled'),
    ('dhanboost_otp', null, 'SERVICE', 'ACTIVE', 'dhanboost_otp'),
    ('dueamount_164', null, 'SERVICE', 'ACTIVE', 'dueamount_164'),
    ('db_overdue_soft_d7_v1_164', $t$Dear {{1}}, this is a gentle reminder that repayment of {{2}} on your DhanBoost loan {{3}} has been pending for {{4}} day(s). If you have already paid, please ignore this message. You can pay using the button below. If you are facing difficulty, please call us on 8510028510 and we will help you.$t$, 'SERVICE', 'ACTIVE', 'db_overdue_soft_d7_v1_164'),
    ('db_overdue_soft_d15_v1_164', $t$Dear {{1}}, repayment of {{2}} on your DhanBoost loan {{3}} has been pending for {{4}} days. Paying soon helps keep your credit history in good standing. You can pay using the button below. If you are facing difficulty, please call us on 8510028510 and we will help you.$t$, 'SERVICE', 'ACTIVE', 'db_overdue_soft_d15_v1_164'),
    ('db_overdue_soft_d30_v1_164', $t$Dear {{1}}, repayment of {{2}} on your DhanBoost loan {{3}} has been pending for {{4}} days. We would like to help you close this loan. Please pay using the button below, or speak to us about your situation. If you are facing difficulty, please call us on 8510028510 and we will help you.$t$, 'SERVICE', 'ACTIVE', 'db_overdue_soft_d30_v1_164'),
    ('db_reported_soft_v1_164', $t$Dear {{1}}, the overdue status of repayment of {{2}} on your DhanBoost loan {{3}} has been shared with credit bureaus by your lender, MLB Securities Private Limited, as lenders are required to do. You can pay using the button below. If you believe this is wrong, write to grievance@dhanboost.com so it can be checked and corrected.$t$, 'SERVICE', 'ACTIVE', 'db_reported_soft_v1_164'),
    ('db_overdue_strict_d7_v1_164', $t$Dear {{1}}, repayment of {{2}} on your DhanBoost loan {{3}} is overdue by {{4}} day(s) and needs your immediate attention. A late charge of 2% per day on the principal applies, for up to 30 days. Overdue loans are reported by your lender, MLB Securities Private Limited, to credit bureaus, and this can lower your credit score. Please pay today using the button below.$t$, 'SERVICE', 'ACTIVE', 'db_overdue_strict_d7_v1_164'),
    ('db_overdue_strict_d15_v1_164', $t$Dear {{1}}, repayment of {{2}} on your DhanBoost loan {{3}} is overdue by {{4}} days and needs your immediate attention. Overdue loans are reported by your lender, MLB Securities Private Limited, to credit bureaus such as CIBIL, CRIF, Experian and Equifax. A poor repayment record can lead to other lenders declining your loan and credit card applications. Please pay today using the button below.$t$, 'SERVICE', 'ACTIVE', 'db_overdue_strict_d15_v1_164'),
    ('db_overdue_strict_d30_v1_164', $t$Dear {{1}}, repayment of {{2}} on your DhanBoost loan {{3}} is overdue by {{4}} days and remains unpaid after earlier reminders. Overdue loans are reported by your lender, MLB Securities Private Limited, to credit bureaus, and a default can stay visible to other lenders on your credit report. The lender may also take lawful recovery steps under your loan agreement. Please pay today using the button below.$t$, 'SERVICE', 'ACTIVE', 'db_overdue_strict_d30_v1_164'),
    ('db_reported_strict_v1_164', $t$Dear {{1}}, repayment of {{2}} on your DhanBoost loan {{3}} has been reported as overdue to credit bureaus by your lender, MLB Securities Private Limited. This can lower your credit score, and other lenders can see it. Please pay today using the button below. Your payment will also be reported. If you believe this is wrong, write to grievance@dhanboost.com so it can be checked and corrected.$t$, 'SERVICE', 'SUBMITTED', 'db_reported_strict_v1_164'),
    ('db_cost_clock_v1_164', $t$Dear {{1}}, repayment of {{2}} on your DhanBoost loan {{3}} is overdue. A late charge of {{4}} is being added each day, for up to 30 days of delay. Paying in full today stops further charges. You can pay using the button below.$t$, 'SERVICE', 'ACTIVE', 'db_cost_clock_v1_164'),
    ('db_eligibility_window_v1_164', $t$Dear {{1}}, repayment of {{2}} on your DhanBoost loan {{3}} is overdue. If it is paid in full by {{4}}, you will remain eligible to apply for future DhanBoost loans, subject to assessment. You can pay using the button below.$t$, 'SERVICE', 'ACTIVE', 'db_eligibility_window_v1_164'),
    ('db_salary_day_v1_164', $t$Dear {{1}}, as your salary is expected around {{2}}, please set aside {{3}} for your overdue DhanBoost loan {{4}} and pay using the button below.$t$, 'SERVICE', 'ACTIVE', 'db_salary_day_v1_164'),
    ('db_ptp_confirmation_v1_164', $t$Dear {{1}}, thank you for confirming that you will pay {{2}} on DhanBoost loan {{3}} by {{4}}. This commitment has been noted on your account. You can pay using the button below.$t$, 'SERVICE', 'ACTIVE', 'db_ptp_confirmation_v1_164'),
    ('db_ptp_missed_v1_164', $t$Dear {{1}}, we did not receive the payment of {{2}} you committed to make by {{3}} on DhanBoost loan {{4}}. Please pay today, or call 8510028510 to give us a revised date.$t$, 'SERVICE', 'ACTIVE', 'db_ptp_missed_v1_164'),
    ('db_part_payment_v1_164', $t$Dear {{1}}, if you cannot pay the full {{2}} on DhanBoost loan {{3}} today, a part payment is accepted and will reduce your outstanding balance. Full repayment remains due. You can pay using the button below.$t$, 'SERVICE', 'ACTIVE', 'db_part_payment_v1_164'),
    ('db_officer_assigned_v1_164', $t$Dear {{1}}, your overdue DhanBoost loan {{2}} has been assigned to {{3}} of our collections team, reachable on {{4}}, to discuss repayment.$t$, 'SERVICE', 'ACTIVE', 'db_officer_assigned_v1_164'),
    ('db_no_response_v1_164', $t$Dear {{1}}, we have tried to reach you about repayment of {{2}} on DhanBoost loan {{3}} and have not received a response. Please call 8510028510 today so that we can discuss this with you.$t$, 'SERVICE', 'ACTIVE', 'db_no_response_v1_164'),
    ('db_settlement_offer_v1_164', $t$Dear {{1}}, an approved settlement of {{2}} is available on your DhanBoost loan {{3}}, valid until {{4}}. A settled account may be reported as settled to credit bureaus. You can pay using the button below.$t$, 'SERVICE', 'ACTIVE', 'db_settlement_offer_v1_164'),
    ('db_senior_review_v1_164', $t$Dear {{1}}, as repayment of {{2}} on your DhanBoost loan {{3}} remains unpaid after {{4}} days, your account has been referred to the senior collections team of your lender, MLB Securities Private Limited, for review of next steps under your loan agreement.$t$, 'SERVICE', 'ACTIVE', 'db_senior_review_v1_164'),
    ('db_notice_issued_v1_164', $t$Dear {{1}}, a formal notice regarding the unpaid amount of {{2}} on your DhanBoost loan {{3}} was issued on {{4}} by your lender, MLB Securities Private Limited. Please read it and respond within the time stated in it.$t$, 'SERVICE', 'ACTIVE', 'db_notice_issued_v1_164'),
    ('db_visit_notice_v1_164', $t$Dear {{1}}, regarding your overdue DhanBoost loan {{2}}, our authorised representative {{3}} will visit on {{4}}. Please carry out identity verification before making any payment.$t$, 'SERVICE', 'ACTIVE', 'db_visit_notice_v1_164'),
    ('db_repay_discount_v1_164', null, 'MARKETING', 'ACTIVE', 'db_repay_discount_v1_164'),
    ('db_repay_discount_review_v1_164', null, 'MARKETING', 'ACTIVE', 'db_repay_discount_review_v1_164'),
    ('db_reference_added_v1_164', $t$Dear {{1}}, {{2}} has named you as a reference for a loan application with DhanBoost and gave us your mobile number for this purpose. If you did not agree to this, or do not know this person, please call us on 8510028510 and we will remove your number.$t$, 'SERVICE', 'ACTIVE', 'db_reference_added_v1_164')
) as v(name, body, category, status, provider)
on conflict (channel, name) do nothing;
